import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.Crpw6aS5.js";const c=JSON.parse('{"title":"逆向思维 Contrarian Thinking","description":"别人贪婪时我恐惧，别人恐惧时我贪婪","frontmatter":{"title":"逆向思维 Contrarian Thinking","description":"别人贪婪时我恐惧，别人恐惧时我贪婪"},"headers":[],"relativePath":"02_concepts/contrarian.md","filePath":"02_concepts/contrarian.md"}'),l={name:"02_concepts/contrarian.md"};function h(i,t,n,s,u,q){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="逆向思维-contrarian-thinking" tabindex="-1">逆向思维 Contrarian Thinking <a class="header-anchor" href="#逆向思维-contrarian-thinking" aria-label="Permalink to &quot;逆向思维 Contrarian Thinking&quot;">​</a></h1><blockquote><p>&quot;别人恐惧时我贪婪，别人贪婪时我恐惧。&quot; ——沃伦·巴菲特</p></blockquote><hr><h2 id="_1960s-逆向的早期实践" tabindex="-1">1960s：逆向的早期实践 <a class="header-anchor" href="#_1960s-逆向的早期实践" aria-label="Permalink to &quot;1960s：逆向的早期实践&quot;">​</a></h2><h3 id="dempster-农机公司" tabindex="-1">Dempster 农机公司 <a class="header-anchor" href="#dempster-农机公司" aria-label="Permalink to &quot;Dempster 农机公司&quot;">​</a></h3><p>1960年代，巴菲特买入了被市场抛弃的 Dempster 农机公司。这是一家传统农具企业，在当时的投资主流眼中毫无吸引力——没有成长性、不属于热门行业、机构避而远之。</p><p>但巴菲特看到的却是：一家现金流扎实、资产被严重低估的企业。当所有人都在追逐成长股时，他选择买入&quot;便宜货&quot;。</p><blockquote><p>&quot;市场先生情绪不稳定，你完全可以不理他，利用他的价格，不要被他影响。&quot;</p></blockquote><hr><h2 id="_1970s-华盛顿邮报的经典案例" tabindex="-1">1970s：华盛顿邮报的经典案例 <a class="header-anchor" href="#_1970s-华盛顿邮报的经典案例" aria-label="Permalink to &quot;1970s：华盛顿邮报的经典案例&quot;">​</a></h2><h3 id="_1973年-买入华盛顿邮报" tabindex="-1">1973年：买入华盛顿邮报 <a class="header-anchor" href="#_1973年-买入华盛顿邮报" aria-label="Permalink to &quot;1973年：买入华盛顿邮报&quot;">​</a></h3><p>1973年，华盛顿邮报的市场价值仅约1亿美元，但巴菲特估算其内在价值在4-5亿美元之间。</p><blockquote><p>&quot;所有机构都不买，因为有效市场理论说市场永远是对的。&quot;</p></blockquote><p>当时的市场环境：水门事件、越战泥潭、经济滞胀，媒体股不受待见。但巴菲特看到的是一家拥有垄断性报纸资产、现金流稳定的企业，被市场恐慌情绪错杀。</p><p>这次投资最终为伯克希尔带来了超过百倍的回报。</p><hr><h2 id="_1980s-逆向思维的系统阐述" tabindex="-1">1980s：逆向思维的系统阐述 <a class="header-anchor" href="#_1980s-逆向思维的系统阐述" aria-label="Permalink to &quot;1980s：逆向思维的系统阐述&quot;">​</a></h2><h3 id="_1987年股灾" tabindex="-1">1987年股灾 <a class="header-anchor" href="#_1987年股灾" aria-label="Permalink to &quot;1987年股灾&quot;">​</a></h3><p>1987年10月19日，&quot;黑色星期一&quot;，道琼斯指数单日暴跌22.6%。市场陷入极度恐慌。</p><p>巴菲特后来反思：&quot;我在1987年10月19日没有行动，那是个错误。&quot;</p><p>但他在此后系统阐述了逆向思维的核心原则：</p><blockquote><p>&quot;别人恐惧时我贪婪，别人贪婪时我恐惧。价格跌了你能买到更便宜，只有被逼卖的时候才会受伤。&quot;</p></blockquote><p>这句话后来成为投资界最广为流传的格言之一。</p><hr><h2 id="_1990s-市场先生的寓言" tabindex="-1">1990s：市场先生的寓言 <a class="header-anchor" href="#_1990s-市场先生的寓言" aria-label="Permalink to &quot;1990s：市场先生的寓言&quot;">​</a></h2><h3 id="_1990年-关于-市场先生" tabindex="-1">1990年：关于&quot;市场先生&quot; <a class="header-anchor" href="#_1990年-关于-市场先生" aria-label="Permalink to &quot;1990年：关于&quot;市场先生&quot;&quot;">​</a></h3><p>巴菲特用格雷厄姆的&quot;市场先生&quot;寓言，进一步阐释逆向思维的本质：</p><blockquote><p>&quot;市场先生情绪不稳定，你完全可以不理他，利用他的价格，不要被他影响。&quot;</p></blockquote><p>市场先生每天报出一个价格，有时极度乐观，有时极度悲观。聪明的投资者利用他的情绪，而不是被他的情绪左右。</p><hr><h2 id="_2000s-金融危机中的大抄底" tabindex="-1">2000s：金融危机中的大抄底 <a class="header-anchor" href="#_2000s-金融危机中的大抄底" aria-label="Permalink to &quot;2000s：金融危机中的大抄底&quot;">​</a></h2><h3 id="_2008年金融危机" tabindex="-1">2008年金融危机 <a class="header-anchor" href="#_2008年金融危机" aria-label="Permalink to &quot;2008年金融危机&quot;">​</a></h3><p>2008年，次贷危机引发全球金融海啸。雷曼兄弟倒闭，AIG濒临破产，市场陷入极度恐慌。</p><p>巴菲特却在众人恐惧中大举出手——投资高盛、通用电气，发表《买入美国》的宣言。</p><blockquote><p>&quot;恐惧心理在短期内占据主导时，股票被抛售至远低于内在价值。&quot;</p></blockquote><p>他在2009年致股东信中写道：</p><blockquote><p>&quot;恐惧是传染病。2008年秋天，这种疾病从纽约的银行和经纪人传播到各地。人们被恐惧感染——包括一些本应理智的投资者。&quot;</p></blockquote><hr><h2 id="_2010s-恐慌的周期性" tabindex="-1">2010s：恐慌的周期性 <a class="header-anchor" href="#_2010s-恐慌的周期性" aria-label="Permalink to &quot;2010s：恐慌的周期性&quot;">​</a></h2><h3 id="_2016年-关于恐慌的频率" tabindex="-1">2016年：关于恐慌的频率 <a class="header-anchor" href="#_2016年-关于恐慌的频率" aria-label="Permalink to &quot;2016年：关于恐慌的频率&quot;">​</a></h3><p>巴菲特在2016年致股东信中总结：</p><blockquote><p>&quot;经济意外是常有的事，但人类恐慌则更加频繁。&quot;</p></blockquote><p>他提醒投资者：每隔十年左右，乌云就会笼罩经济的天空。但天空会再次晴朗，关键在于你是否准备好了。</p><blockquote><p>&quot;在那种时候，我们应该低下头，利用这个机会——前提是我们已经准备好了。&quot;</p></blockquote><hr><h2 id="_2020s-百年一遇的疫情" tabindex="-1">2020s：百年一遇的疫情 <a class="header-anchor" href="#_2020s-百年一遇的疫情" aria-label="Permalink to &quot;2020s：百年一遇的疫情&quot;">​</a></h2><h3 id="_2020年-新冠疫情" tabindex="-1">2020年：新冠疫情 <a class="header-anchor" href="#_2020年-新冠疫情" aria-label="Permalink to &quot;2020年：新冠疫情&quot;">​</a></h3><p>2020年3月，新冠疫情全球爆发，美股四次熔断，市场陷入极度恐慌。</p><p>巴菲特在股东大会上坦言：</p><blockquote><p>&quot;这是我有生以来最可怕的一次，恐惧让优秀企业股价跌到不可思议的低位。&quot;</p></blockquote><p>尽管当时伯克希尔账上现金充裕，但巴菲特承认这次没有大规模出手——航空股的教训让他更加谨慎。但这并不改变逆向思维的核心原则：极端恐慌时刻，往往是最好的买入时机。</p><hr><h2 id="逆向思维的本质" tabindex="-1">逆向思维的本质 <a class="header-anchor" href="#逆向思维的本质" aria-label="Permalink to &quot;逆向思维的本质&quot;">​</a></h2><h3 id="不是简单的-反着来" tabindex="-1">不是简单的&quot;反着来&quot; <a class="header-anchor" href="#不是简单的-反着来" aria-label="Permalink to &quot;不是简单的&quot;反着来&quot;&quot;">​</a></h3><p>逆向思维不等于故意唱反调。巴菲特的逆向建立在扎实的研究和独立判断之上。</p><blockquote><p>&quot;你的行为必须与众不同，但如果你错误地逆向，那将是最糟糕的事情。&quot;</p></blockquote><h3 id="等待极端而不是寻找平庸" tabindex="-1">等待极端而不是寻找平庸 <a class="header-anchor" href="#等待极端而不是寻找平庸" aria-label="Permalink to &quot;等待极端而不是寻找平庸&quot;">​</a></h3><p>巴菲特不是在市场稍微悲观时买入，而是在极端恐慌或贪婪的时刻出手。</p><blockquote><p>&quot;关键不是在别人贪婪时恐惧，或者在别人恐惧时贪婪。关键是在极度贪婪和极度恐惧的时刻采取行动。&quot;</p></blockquote><h3 id="需要勇气-更需要准备" tabindex="-1">需要勇气，更需要准备 <a class="header-anchor" href="#需要勇气-更需要准备" aria-label="Permalink to &quot;需要勇气，更需要准备&quot;">​</a></h3><blockquote><p>&quot;投资的成功与你有多聪明关系不大。真正重要的是你是否有一种既能让你在别人恐慌时保持理性，又能在机会出现时果断行动的性情。&quot;</p></blockquote><hr><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该主题在致股东信中的关键原文出处年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=核心总结">1987年：核心总结</a> → <a href="/01_letters/1987年/翻译.html">/01_letters/1987年/翻译</a></li><li><a href="/search.html?q=核心总结">1994年：核心总结</a> → <a href="/01_letters/1994年/翻译.html">/01_letters/1994年/翻译</a></li><li><a href="/search.html?q=核心总结">2008年：核心总结</a> → <a href="/01_letters/2008年/翻译.html">/01_letters/2008年/翻译</a></li><li><a href="/search.html?q=核心总结">2009年：核心总结</a> → <a href="/01_letters/2009年/翻译.html">/01_letters/2009年/翻译</a></li><li><a href="/search.html?q=核心总结">2020年：核心总结</a> → <a href="/01_letters/2020年/翻译.html">/01_letters/2020年/翻译</a></li></ul><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/1987年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">&quot;别人贪婪时我恐惧&quot;经典阐述</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1994年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">棒球理论：不挥棒不会三振出局</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2008年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">金融危机中的逆向买入</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2009年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">&quot;也许十年最悲观的时候&quot;</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2020年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">百年一遇疫情中的机会</td></tr></tbody></table>',67)])])}const p=a(l,[["render",h]]);export{c as __pageData,p as default};
